	@Test
	void agreesWithIndependentBagExpansionAcrossRandomFanoutDensityAndThresholds() {
		Random random = new Random(0x7e55e4a);
		for (int iteration = 0; iteration < 120; iteration++) {
			int shared = 1 + random.nextInt(24);
			List<Row> left = randomRows(random, 1 + random.nextInt(20), shared, 100, 1000);
			List<Row> right = randomRows(random, shared, 1 + random.nextInt(35), 1000, 10000);
			for (long minimum : new long[] { 0, 1, 2, 8, 40, 200 }) {
				assertEquals(reference(left, right, minimum), multiply(left, right, minimum).counts,
						"iteration=" + iteration + " minimum=" + minimum);
			}
		}
	}

