		Rows right = new Rows(List.of(new Row(1000, neighbors, weights)));
		AtomicInteger pollsAfterPreparation = new AtomicInteger();
		AtomicInteger emitted = new AtomicInteger();
		TrackingMemory memory = new TrackingMemory(Long.MAX_VALUE);
