	private static Outcome multiply(List<Row> left, List<Row> right, long minimum) {
		Map<Pair, Long> result = new HashMap<>();
		TrackingMemory memory = new TrackingMemory(Long.MAX_VALUE);
		SparseJoinAggregateKernel.Statistics stats = SparseJoinAggregateKernel.multiply(new Rows(left), new Rows(right),
				minimum, (a, b, count) -> {
					assertTrue(count > 0L);
					assertFalse(result.containsKey(new Pair(a, b)), "group emitted twice");
					result.put(new Pair(a, b), count);
				}, memory, null);
		assertEquals(0, memory.used);
		return new Outcome(result, stats);
	}

	private static Map<Pair, Long> reference(List<Row> left, List<Row> right, long minimum) {
		Map<Pair, Long> result = new HashMap<>();
		for (Row a : left) {
			for (int i = 0; i < a.neighbors.length; i++) {
				for (Row b : right) {
					if (a.neighbors[i] == b.key) {
						for (int j = 0; j < b.neighbors.length; j++) {
							Pair pair = new Pair(a.key, b.neighbors[j]);
							result.merge(pair, Math.multiplyExact(a.weights[i], b.weights[j]), Math::addExact);
						}
					}
				}
			}
		}
		result.values().removeIf(count -> count < minimum);
		return result;
	}

	private static List<Row> randomRows(Random random, int rows, int domain, long keyBase, long neighborBase) {
		List<Row> result = new ArrayList<>();
		for (int row = 0; row < rows; row++) {
			Map<Long, Long> entries = new TreeMap<>();
			for (int item = random.nextInt(domain + 1); item > 0; item--) {
				entries.merge(neighborBase + random.nextInt(domain), 1L + random.nextInt(4), Long::sum);
			}
			result.add(new Row(keyBase + row, entries.keySet().stream().mapToLong(Long::longValue).toArray(),
					entries.values().stream().mapToLong(Long::longValue).toArray()));
		}
		return result;
	}

	private static Row row(long key, long... pairs) {
		long[] neighbors = new long[pairs.length / 2], weights = new long[pairs.length / 2];
		for (int i = 0; i < neighbors.length; i++) {
			neighbors[i] = pairs[i * 2];
			weights[i] = pairs[i * 2 + 1];
		}
		return new Row(key, neighbors, weights);
	}

	private record Pair(long left, long right) {
	}

	private record Row(long key, long[] neighbors, long[] weights) {
	}

	private record Outcome(Map<Pair, Long> counts, SparseJoinAggregateKernel.Statistics statistics) {
	}

	private static final class Rows implements SparseJoinAggregateKernel.WeightedRows {
		private final List<Row> rows;
		private int row = -1, offset;
		private boolean exhausted;

		Rows(List<Row> rows) {
			this.rows = rows;
		}

		@Override
		public boolean nextRow() {
			offset = 0;
			exhausted = ++row == rows.size();
			return !exhausted;
		}

		@Override
		public long key() {
			return rows.get(row).key;
		}

		@Override
		public int read(long[] neighbors, long[] weights) {
			Row current = rows.get(row);
			int count = Math.min(neighbors.length, current.neighbors.length - offset);
			System.arraycopy(current.neighbors, offset, neighbors, 0, count);
			System.arraycopy(current.weights, offset, weights, 0, count);
			offset += count;
			return count;
		}
	}

	private static final class TrackingMemory implements KernelRuntime.MemoryAccount {
		private final long limit;
		private long used, peak;

		TrackingMemory(long limit) {
			this.limit = limit;
		}

		@Override
		public boolean tryReserve(long bytes) {
			if (bytes > limit - used) {
				return false;
			}
			used += bytes;
			peak = Math.max(peak, used);
			return true;
		}

		@Override
		public void release(long bytes) {
			assertTrue(bytes >= 0 && bytes <= used);
			used -= bytes;
		}
	}
